const ChevronIcon = ({ expanded }: { expanded?: boolean }) => (
  <svg
    width="12"
    height="12"
    viewBox="0 0 12 12"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className={`transition-transform ${expanded ? "rotate-180" : ""}`}
  >
    <path d="M2 4L6 8L10 4" stroke="#777777" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
);

export function VendorSidebar() {
  const pathname = usePathname();
  const [expandedItem, setExpandedItem] = useState<string | null>(null);

  // Auto-expand Jobs menu when on a jobs page
  useEffect(() => {
    if (pathname.startsWith("/vendor/jobs")) {
      setExpandedItem("Jobs");
    }
  }, [pathname]);

  const isActive = (href: string) => {
    if (href === "/vendor/dashboard") {
      return pathname === href || pathname === "/vendor";
    }
    return pathname.startsWith(href);
  };

  const toggleDropdown = (label: string, e: React.MouseEvent) => {
    e.preventDefault();
    setExpandedItem(expandedItem === label ? null : label);
  };

  const mainNavItems = [
    { label: "Dashboard", href: "/vendor/dashboard", Icon: DashboardIcon },
    {
      label: "Jobs",
      href: "/vendor/jobs",
      Icon: JobsIcon,
      hasDropdown: true,
      subItems: [
        { label: "Job Requests", href: "/vendor/jobs" },
        { label: "All Bookings", href: "/vendor/jobs/bookings" },
      ],
    },
    { label: "Disputes", href: "/vendor/disputes", Icon: DisputesIcon },
    { label: "Uniform & Workwear", href: "/vendor/uniform", Icon: UniformIcon },
    { label: "Transactions", href: "/vendor/transactions", Icon: TransactionsIcon },
    { label: "Services & Availability", href: "/vendor/services", Icon: ServicesIcon },
  ];

  const bottomNavItems = [
    { label: "Help Center", href: "/vendor/help", Icon: HelpIcon },
    { label: "Settings", href: "/vendor/settings", Icon: SettingsIcon },
    { label: "Profile", href: "/vendor/profile", Icon: ProfileIcon },
  ];

  return (
    <aside className="fixed left-0 top-0 bottom-0 w-[248px] bg-white border-r border-[rgba(0,0,0,0.1)] flex flex-col justify-between p-4 z-50">
      {/* Top Section */}
      <div className="flex flex-col gap-12 items-center w-full">
        {/* Logo */}
        <div className="w-full bg-[#02368c] rounded-[5px] py-[11px]">
          <Link
            href="/vendor/dashboard"
            className="flex items-center justify-center gap-3"
          >
            <div className="relative w-[43px] h-[42px]">
              <Image
                src="/images/vendor/icons/wallkas-logo-icon.svg"
                alt="Wallkas"
                fill
                className="object-contain"
              />
            </div>
            <div className="flex flex-col gap-[1px] text-center uppercase">
              <span className="text-white text-[18px] tracking-[1.8px] font-normal">
                wallkas
              </span>
              <span className="text-[#dca700] text-[6px] tracking-[1.1px] font-normal font-['Roboto_Condensed']">
                your space, our care
              </span>
            </div>
          </Link>
        </div>

        {/* Main Navigation */}
        <nav className="w-full">
          <ul className="flex flex-col">
            {mainNavItems.map((item) => {
              const active = isActive(item.href);
              const Icon = item.Icon;
              const isExpanded = expandedItem === item.label;
              return (
                <li key={item.label}>
                  <Link
                    href={item.hasDropdown ? "#" : item.href}
                    onClick={
                      item.hasDropdown
                        ? (e) => toggleDropdown(item.label, e)
                        : undefined
                    }
                    className={`flex items-center gap-2 h-14 px-3 py-2 rounded-lg transition-colors ${
                      active && !item.hasDropdown ? "bg-[#eff6ff]" : "hover:bg-[#f8fafc]"
                    }`}
                  >
                    <div className="w-6 h-6 flex items-center justify-center shrink-0">
                      <Icon active={active} />
                    </div>
                    <span
                      className={`flex-1 text-[14px] font-normal leading-[1.2] ${
                        active ? "text-[#02368c]" : "text-[#777]"
                      }`}
                      style={{ fontFamily: "Roboto, sans-serif" }}
                    >
                      {item.label}
                    </span>
                    {item.hasDropdown && (
                      <ChevronIcon expanded={isExpanded} />
                    )}
                  </Link>
                  {/* Sub-items */}
                  {item.hasDropdown && item.subItems && isExpanded && (
                    <ul className="flex flex-col ml-8 mt-1">
                      {item.subItems.map((subItem) => {
                        const subActive = pathname === subItem.href;
                        return (
                          <li key={subItem.label}>
                            <Link
                              href={subItem.href}
                              className={`flex items-center h-10 px-3 py-2 rounded-lg transition-colors ${
                                subActive ? "bg-[#eff6ff] text-[#02368c]" : "text-[#777] hover:bg-[#f8fafc]"
                              }`}
                            >
                              <span
                                className="text-[13px] font-normal leading-[1.2]"
                                style={{ fontFamily: "Roboto, sans-serif" }}
                              >
                                {subItem.label}
                              </span>
                            </Link>
                          </li>
                        );
                      })}
                    </ul>
                  )}
                </li>
              );
            })}
          </ul>
        </nav>
      </div>

      {/* Bottom Navigation */}
      <div className="border-t border-[rgba(68,68,68,0.3)] pt-4 w-full">
        <ul className="flex flex-col">
          {bottomNavItems.map((item) => {
            const active = isActive(item.href);
            const Icon = item.Icon;
            return (
              <li key={item.label}>
                <Link
                  href={item.href}
                  className={`flex items-center gap-2 h-14 px-3 py-2 rounded-lg transition-colors ${
                    active ? "bg-[#eff6ff]" : "hover:bg-[#f8fafc]"
                  }`}
                >
                  <div className="w-6 h-6 flex items-center justify-center shrink-0">
                    <Icon active={active} />
                  </div>
                  <span
                    className={`flex-1 text-[14px] font-normal leading-[1.2] ${
                      active ? "text-[#02368c]" : "text-[#777]"
                    }`}
                    style={{ fontFamily: "Roboto, sans-serif" }}
                  >
                    {item.label}
                  </span>
                </Link>
              </li>
            );
          })}
        </ul>
      </div>
    </aside>
  );
}
